## Code Example
```typescript
interface IEvictionPolicy {
  onAccess(key: string): void
  onPut(key: string, value: any): void
  onEvict(key: string): void
}
class PolicyRegistry {
  private map = new Map<string, () => IEvictionPolicy>();
  register(name: string, ctor: () => IEvictionPolicy){ this.map.set(name, ctor) }
  get(name: string){ return this.map.get(name)!.call(null) }
}
```

